"""Generated by Codex. Regression tests for local act preflight checks."""

import json
import os
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch

import act_preflight


class PreflightTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name).resolve()
        subprocess.run(["git", "init", "-q", str(self.root)], check=True)

    def track(self, name):
        path = self.root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("fixture")
        subprocess.run(["git", "add", "--", name], cwd=self.root, check=True)
        return path

    def test_bind_aliases_and_clusters(self):
        for flag in ("--bind", "--bind=true", "--bind=1", "--bind=T", "-b", "-b=true", "-vb"):
            with self.subTest(flag=flag), self.assertRaises(RuntimeError):
                act_preflight.check_arguments([flag])
        act_preflight.check_arguments(["--bind=false", "-b=0", "--verbose", "workflow_dispatch"])

    @unittest.skipIf(os.geteuid() == 0, "Root can read mode-000 files")
    def test_reports_all_unreadable_candidates(self):
        tracked = self.track("tracked file")
        untracked = self.root / "untracked"
        untracked.write_text("do not disclose this content")
        tracked.chmod(0)
        untracked.chmod(0)
        with self.assertRaises(RuntimeError) as error:
            act_preflight.check_sources(self.root)
        self.assertIn("tracked file", str(error.exception))
        self.assertIn("untracked", str(error.exception))
        self.assertNotIn("do not disclose", str(error.exception))
        self.assertEqual(tracked.stat().st_mode & 0o777, 0)

    def test_deleted_ignored_and_symlink_files(self):
        self.track("deleted").unlink()
        (self.root / ".gitignore").write_text("target/\n")
        (self.root / "target").mkdir()
        ignored = self.root / "target/cache"
        ignored.write_text("ignored")
        ignored.chmod(0)
        (self.root / "link").symlink_to("missing")
        act_preflight.check_sources(self.root)

    @unittest.skipIf(os.geteuid() == 0, "Root can traverse mode-000 directories")
    def test_inaccessible_directory(self):
        path = self.track("private/file").parent
        path.chmod(0)
        try:
            with self.assertRaises(RuntimeError):
                act_preflight.check_sources(self.root)
        finally:
            path.chmod(0o755)

    def test_git_warning_is_not_silently_ignored(self):
        result = subprocess.CompletedProcess([], 0, b"", b"warning: could not open directory 'private/': Permission denied")
        with patch.object(act_preflight.subprocess, "run", return_value=result):
            with self.assertRaisesRegex(RuntimeError, "Cannot enumerate"):
                act_preflight.check_sources(self.root)

    def containers(self, mounts):
        return [
            subprocess.CompletedProcess([], 0, "abcdef\n", ""),
            subprocess.CompletedProcess([], 0, json.dumps([
                {"Id": "abcdef", "Name": "/act-fixture", "Mounts": mounts}
            ]), ""),
        ]

    def test_stale_bind_rejected_without_mutation(self):
        alias = self.root / "alias"
        alias.symlink_to(self.root, target_is_directory=True)
        with patch.object(act_preflight.subprocess, "run", side_effect=self.containers([
            {"Type": "bind", "Source": str(alias)}
        ])) as run:
            with self.assertRaisesRegex(RuntimeError, "abcdef"):
                act_preflight.check_containers(self.root)
            self.assertEqual([call.args[0][1] for call in run.call_args_list], ["ps", "inspect"])

    def test_isolated_and_unrelated_mounts_allowed(self):
        with patch.object(act_preflight.subprocess, "run", side_effect=self.containers([
            {"Type": "volume", "Source": "/var/lib/docker/volumes/workspace"},
            {"Type": "bind", "Source": "/var/run/docker.sock"},
            {"Type": "bind", "Source": str(self.root) + "-other"},
        ])):
            act_preflight.check_containers(self.root)

    def test_docker_failure_blocks_run(self):
        with patch.object(act_preflight.subprocess, "run", side_effect=subprocess.CalledProcessError(1, "docker", stderr="permission denied")):
            with self.assertRaises(subprocess.CalledProcessError):
                act_preflight.check_containers(self.root)

    def test_wrapper_preflight_prevents_act_start(self):
        scripts = self.root / "script/ci"
        scripts.mkdir(parents=True)
        original = Path(__file__).parent
        for name in ("act.sh", "act_preflight.py"):
            (scripts / name).write_text((original / name).read_text())
        binary = self.root / "bin"
        binary.mkdir()
        marker = self.root / "act-started"
        act = binary / "act"
        act.write_text('#!/bin/sh\ntouch "$ACT_MARKER"\n')
        act.chmod(0o755)
        result = subprocess.run(
            ["bash", str(scripts / "act.sh"), "--", "--bind"],
            env=dict(os.environ, PATH=str(binary) + ":" + os.environ["PATH"], ACT_MARKER=str(marker)),
            capture_output=True, text=True,
        )
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("Bind mode is disabled", result.stderr)
        self.assertFalse(marker.exists())
        self.assertFalse((self.root / "logs").exists())

    def test_wrapper_success_and_failure_with_isolation(self):
        scripts = self.root / "script/ci"
        scripts.mkdir(parents=True)
        for name in ("act.sh", "act_preflight.py"):
            (scripts / name).write_text((Path(__file__).parent / name).read_text())
        binary = self.root / "bin"
        binary.mkdir()
        for name, body in {
            "docker": 'test "$1" = ps || exit 99\n',
            "act": 'printf "%s\\n" "$@" > "$ACT_ARGS_FILE"\nexit "$ACT_STATUS"\n',
        }.items():
            executable = binary / name
            executable.write_text("#!/bin/sh\n" + body)
            executable.chmod(0o755)
        args_file = self.root / "arguments"
        for status in (0, 17):
            result = subprocess.run(
                ["bash", str(scripts / "act.sh"), "-j", "fixture"],
                env=dict(os.environ, PATH=str(binary) + ":" + os.environ["PATH"],
                         ACT_ARGS_FILE=str(args_file), ACT_STATUS=str(status)),
                capture_output=True, text=True,
            )
            self.assertEqual(result.returncode, 0 if status == 0 else 1, result.stderr)
            self.assertEqual(args_file.read_text().splitlines()[-1], "--bind=false")


if __name__ == "__main__":
    unittest.main()
